local KANTO_PALS = { "PLAYER", "FALKNER", "BROCK", "LT_SURGE", "SABRINA", "JANINE", "BLAINE", "BLUE" }
local JOHTO_FACES = { { 3, 10, 1 }, { 7, 10, 2 }, { 11, 10, 3 }, { 15, 10, 4 },
